/**
 * node tools/build.mjs
 * Verifies, then zips each package for upload to the Chrome Web Store.
 * Day-to-day installing does not need this - load the folders unpacked.
 */
import { spawnSync } from 'node:child_process';
import { mkdirSync, rmSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const verify = spawnSync(process.execPath, ['tools/verify.mjs'], { stdio: 'inherit' });
if (verify.status !== 0) {
  console.log('\nverification failed - not building');
  process.exit(1);
}

// Generated by Chrome or the OS; never part of either package.
const EXCLUDE = ['Cached Theme.pak', 'Thumbs.db', '.DS_Store'];

mkdirSync('dist', { recursive: true });
// One extension plus one theme package per palette.
const isDir = (d) => statSync(join('themes', d)).isDirectory();
const PACKAGES = ['extension', ...readdirSync('themes').filter(isDir).map((d) => 'themes/' + d)];

for (const pkg of PACKAGES) {
  const out = `dist/zero-hour-${pkg.replace('themes/', 'theme-')}.zip`;
  rmSync(out, { force: true });
  // Chrome writes "Cached Theme.pak" into a theme folder when it loads it
  // unpacked - a compiled bundle of whatever the theme looked like at the time.
  // Zipping it bloats the package and ships stale artwork, so it is filtered.
  // Passing the children rather than the folder keeps manifest.json at the root,
  // which is what Chrome requires.
  const ps = `$items = Get-ChildItem -LiteralPath '${pkg}' -Force | ` +
    `Where-Object { $_.Name -notin @(${EXCLUDE.map((e) => `'${e}'`).join(',')}) }; ` +
    `Compress-Archive -Path $items.FullName -DestinationPath '${out}' -Force`;
  const r = spawnSync('powershell', ['-NoProfile', '-NonInteractive', '-Command', ps],
    { stdio: 'inherit' });
  if (r.status !== 0) { console.log(`could not zip ${pkg}`); process.exit(1); }
  console.log(`  ${out}  ${(statSync(out).size / 1024).toFixed(0)} KB`);
}
console.log('\nbuilt.');
